CH = dict(num=12, title="Beyond Earth", theme="Stars, constellations, night sky, Solar System, Moon, galaxy",
 intro="Yangdol and Dorjay in Nubra, Ladakh, watch a star-filled night sky free of air and light pollution. The chapter explains **stars and constellations**, how to watch the night sky and find the **Pole Star**, the members of the **Solar System** (Sun, planets, moons, asteroids, comets), the **Milky Way** galaxy and the Universe.",
 big_questions=["What are constellations and how are they useful?", "How can we find the Pole Star and Orion?", "What does the Solar System contain?", "What lies beyond the Solar System?"],
 blocks=[
 ("h2", "12.1 Stars and Constellations"),
 ("ul", ["Stars **shine with their own light**; some look bright, some dim. Ancient people imagined patterns joining stars into animals, objects or story characters; patterns differ in different cultures.",
  "These patterns helped to **recognise stars and find directions** — at sea or land, even before the magnetic compass; still a backup in emergencies.",
  "A **constellation** was originally a group of stars forming a pattern; now it means a **defined region of the sky**. The **International Astronomical Union (IAU)** fixed boundaries in the early 20th century — **88 constellations** divide the entire sky."]),
 ("table", ["Constellation / star", "Details"],
  [["**Orion** (hunter)", "Three stars in a line in the middle form the hunter's belt; seen with dog **Canis Major** and bull **Taurus**"],
   ["**Sirius**", "In Canis Major; the **brightest star** in the night sky"],
   ["**Betelgeuse** (Ārdrā), **Aldebaran** (Rohini), **Pleiades** (Krittika)", "Indian *nakshatras*: Ardra in Orion; Krittika (Pleiades) and Rohini (Aldebaran) in Taurus"],
   ["**Big Dipper**", "Part of **Ursa Major**; called **Saptarishi** in India"],
   ["**Little Dipper**", "Part of **Ursa Minor**; contains the **Pole Star (Polaris, Dhruva tara)**"],
   ["**Pole Star**", "Appears nearly **stationary in the north**; helps find north in the Northern Hemisphere; not very bright; **not visible from the Southern Hemisphere**"]]),
 ("p", "Stories: tribes of Central India see four Big Dipper stars as a 'grandmother's cot' and three as thieves; Konkan fishermen see a boat."),
 ("h2", "12.2 Night Sky Watching"),
 ("ul", ["**Light pollution** — excessive artificial light at night — along with smoke and dust, hides stars in cities; more stars are visible in villages. Tall buildings and trees also block the view. Dark-sky reserves and parks protect dark skies for research.",
  "Not all constellations are visible from every place or on all nights.",
  "Tools: sky-mapping apps (**Sky Map, Stellarium**), printed charts, a compass, notebook; telescopes and binoculars show dim objects brighter."]),
 ("steps", [("Choose place", "A dark, open area away from lights, tall buildings and trees, with adult supervision (never go alone)."),
  ("Choose time", "Use an app to select date/time; pick a night without Moon or clouds, especially to spot the faint Pole Star."),
  ("Carry", "Sky map or printouts, magnetic compass, notebook."),
  ("Adjust eyes", "Wait about half an hour for your eyes to adapt to the darkness.")]),
 ("ul", ["**Finding the Pole Star:** locate the Big Dipper (look north in summer around 9 p.m.). Imagine a line through the two stars at the end of its cup towards the north; at about **five times** the distance between those two stars lies the Pole Star.", "**Finding Orion:** best seen from India in **December to April** after sunset; find the three bright stars in a short row (belt); extending that line towards the **east** leads to **Sirius**."]),
 ("h2", "12.3 Our Solar System"),
 ("h3", "The Sun"),
 ("ul", ["A **star**, the nearest to us, an extremely hot ball of gases; produces heat and light; main source of energy for Earth — plants, food, oxygen, climate, seasons, weather, winds and the water cycle depend on it. In India the Sun is worshipped as **Surya**.",
  "About **100 times** the Earth's diameter; seems small because of distance (~**150 million km**). One **astronomical unit (au)** is about the Sun–Earth distance.",
  "Other stars are far away, so look like points of light; many are bigger than the Sun. Stars are invisible by day because of the Sun's brightness.",
  "Nearest star after the Sun: **Proxima Centauri**, about **269,000 au** away.",
  "The Sun is the **largest and heaviest** object in the Solar System and gives almost all its energy; other objects shine by **reflected sunlight**."]),
 ("h3", "Planets"),
 ("note", "DEFINITION", "A **planet** is a large, nearly spherical object that **revolves around the Sun**. **Revolution** is the movement of an object around the Sun (or another body). Earth takes **about one year** to revolve and rotates on its axis in about **24 hours** (one day)."),
 ("table", ["Order from Sun", "Planet (Indian name)", "Notes"],
  [["1", "Mercury (Budha)", "Inner rocky planet"],
   ["2", "Venus (Shukra)", "Morning/Evening Star (not a star); brightest after Sun and Moon; hotter than Mercury because its atmosphere traps heat"],
   ["3", "Earth (Prithvi)", "Blue Planet — water covers most of the surface"],
   ["4", "Mars (Mangala)", "Red Planet — reddish soil; two moons"],
   ["5", "Jupiter (Brihaspati/Guru)", "Giant, gas and ice; rings"],
   ["6", "Saturn (Shani)", "Giant; prominent rings"],
   ["7", "Uranus", "Giant, gas and ice"],
   ["8", "Neptune", "Giant, gas and ice"]]),
 ("ul", ["Memory aid: Mercury, Venus, Earth, Mars, Jupiter, Saturn, Uranus, Neptune.", "**Inner four** planets are smaller with solid rocky surfaces; **outer four** are much larger, mostly gas and ice, with **ring systems** of dust and rock.", "Planets are colder generally the farther they are from the Sun; atmosphere can change this.", "**Pluto** lies beyond Neptune, smaller than Earth's Moon; in **2006 IAU** redefined 'planet' and Pluto became a **dwarf planet**.", "Mercury, Venus, Mars, Jupiter and Saturn are visible to the naked eye; **stars twinkle**, planets do not twinkle much. Venus can be seen in the east before sunrise or the west after sunset."]),
 ("h3", "Natural satellites and the Moon"),
 ("ul", ["Objects that move around planets are **satellites**; **moons** are natural satellites. Earth has 1 moon, Mars 2; Jupiter, Saturn, Uranus and Neptune have many.", "The **Moon**: revolves around Earth in about **27 days**; about one-quarter of Earth's diameter; about **3,84,000 km** away; has hardly any atmosphere, water or life; **craters** (bowl-shaped) formed by impacts of asteroids/rocks stay for a very long time.", "**Chandrayaan-1** (2008), **Chandrayaan-2** (2019), **Chandrayaan-3** (July 2023) — Vikram lander with Pragyan rover soft-landed near the Moon's **south pole on 23 August 2023**, a first for any country; 23 August is **National Space Day**. **Chandrayaan-4** is planned to bring back samples."]),
 ("h3", "Asteroids and comets"),
 ("table", ["Object", "Description"],
  [["**Asteroids**", "Small, rocky, irregular; most revolve in the **asteroid belt between Mars and Jupiter**; sizes from ~10 m to ~500 km"],
   ["**Comets**", "Icy-rocky bodies of dust, gas, rock and ice with long **tails**; near the Sun the ice evaporates forming the tail; **Halley's Comet** appears every **76 years** (last in 1986); Sanskrit name *Dhumaketu*"]]),
 ("note", "IMPORTANT", "The **Solar System** = Sun + eight planets + their moons + asteroids, comets and other small objects."),
 ("h2", "12.4 The Milky Way Galaxy"),
 ("p", "A faint band of light across the sky on moonless nights from dark places is our home galaxy, the **Milky Way (Akasha Ganga)**. A **galaxy** has millions to billions of stars; the Solar System is part of it."),
 ("h2", "12.5 The Universe"),
 ("p", "There are many galaxies beyond the Milky Way, and the Universe contains them all. Whether life exists elsewhere is unknown; the search focuses on **exoplanets** — planets around other stars — and no evidence has been found yet."),
 ("h2", "12.6 Likely Exam Questions"),
 ("qa", [("What is a constellation? How many are there?", "A defined region of the sky with a star pattern; 88 officially."),
  ("How were star patterns useful to ancient people?", "To identify stars and find direction at sea and on land."),
  ("How do you locate the Pole Star?", "Extend a line through the two end stars of the Big Dipper's cup about five times their separation."),
  ("Why is the Pole Star important?", "It appears nearly fixed in the north, showing north direction."),
  ("What is light pollution?", "Excess artificial light at night that hides stars."),
  ("Why can't we see stars in the daytime?", "The Sun's brightness outshines them."),
  ("Why does the Sun look bigger than other stars?", "It is much closer to us."),
  ("Define planet and revolution.", "Large nearly spherical body revolving around the Sun; movement around the Sun."),
  ("Name the planets in order from the Sun.", "Mercury, Venus, Earth, Mars, Jupiter, Saturn, Uranus, Neptune."),
  ("Why is Mars called the Red Planet and Earth the Blue Planet?", "Mars has reddish soil; Earth's surface is mostly water."),
  ("Why is Pluto not a planet?", "IAU redefined planet in 2006; Pluto is a dwarf planet."),
  ("What are asteroids and comets?", "Rocky irregular bodies in the asteroid belt; icy bodies with tails near the Sun."),
  ("Write about Chandrayaan-3.", "Launched July 2023; Vikram lander and Pragyan rover landed near Moon's south pole on 23 August 2023, celebrated as National Space Day.")]),
 ],
 takeaways=["Constellations are star patterns/regions (88 in total); Orion, Big Dipper, Little Dipper; the Pole Star shows north.",
  "Light pollution reduces visibility of stars; watch the sky from dark, open places.",
  "The Sun is a star and the main energy source; the Solar System has eight planets, moons, asteroids and comets.",
  "Planets in order: Mercury, Venus, Earth, Mars, Jupiter, Saturn, Uranus, Neptune.",
  "The Moon is Earth's natural satellite and revolves in about 27 days; India's Chandrayaan-3 landed near the south pole.",
  "The Solar System belongs to the Milky Way galaxy within the Universe."])
